def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    def is_expired(write_time, current_time):
        return current_time >= write_time + ttl

    def get_valid_entry(key, current_time):
        if key in cache:
            value, write_time = cache[key]
            if not is_expired(write_time, current_time):
                return value
        return None

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries before processing
            expired_keys = [k for k, (v, wt) in cache.items() if is_expired(wt, t)]
            for k in expired_keys:
                del cache[k]

            # If key exists and is not expired, just update it
            if key in cache and not is_expired(cache[key][1], t):
                cache[key] = (value, t)
                cache.move_to_end(key)  # Mark as most recently used
            else:
                # Key is absent (either doesn't exist or is expired)
                # Check if we need to evict
                if key not in cache and len(cache) >= capacity:
                    # Evict least recently used
                    cache.popitem(last=False)

                cache[key] = (value, t)
                if key in cache:
                    cache.move_to_end(key)  # Mark as most recently used

        elif op[0] == 'get':
            _, t, key = op

            # Don't remove expired entries here; just check if this one is expired
            value = get_valid_entry(key, t)

            if value is not None:
                results.append(value)
                # Mark as most recently used
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

